import { createSearchUtils } from '@wix/sdk-runtime/search-builder-utils'
import type {
  SearchSpec,
  SearchBuilder as SDKSearchBuilder,
  SearchRequest,
  SearchParamsFactory,
} from '@wix/sdk-types'
import type { WixDataItem } from './types'

/**
 * WixData SearchSpec - allows searching/sorting on any string field
 * since WixData collections are dynamic and don't have a fixed schema.
 */
interface WixDataSearchSpec extends SearchSpec {
  wql: [
    {
      fields: string[]
      sort: 'BOTH'
    }
  ]
  paging: 'offset' | 'cursor'
}

type WixDataSearchRequest = SearchRequest<WixDataItem, WixDataSearchSpec>

/**
 * Search builder.
 * @public
 */
export type WixDataSearchBuilder = Omit<
  SDKSearchBuilder<WixDataItem, WixDataSearchSpec, WixDataSearchRequest>,
  'withAggregation' | 'withTimeZone'
>

const searchUtils = createSearchUtils<WixDataItem, WixDataSearchSpec>({
  transformSystemFields: false,
})

/**
 * Creates a new search builder.
 * @public
 *
 * @example
 * ```ts title="Build a search"
 * import { items, SearchBuilder, SearchParams, Filter } from '@wix/data'
 *
 * const request = SearchBuilder()
 *   .withSearch(SearchParams.expression('red car'))
 *   .withFilter(Filter('status').eq('active'))
 *   .withPaging({ limit: 10, offset: 0 })
 *   .build()
 *
 * const result = await items.search('myCollection', request)
 * ```
 */
export const SearchBuilder: () => WixDataSearchBuilder =
  searchUtils.SearchBuilder

/**
 * Search parameter factory for creating search expressions.
 * @public
 *
 * @example
 * ```ts title="Create search parameters"
 * import { SearchParams } from '@wix/data'
 * // Simple expression
 * SearchParams.expression('search text')
 *
 * // Fuzzy search
 * SearchParams.fuzzy(true)
 *
 * // AND mode (all terms must match)
 * SearchParams.mode('AND')
 * ```
 */
export const SearchParams: SearchParamsFactory<WixDataSearchSpec> =
  searchUtils.SearchParams
